<div class="witch-keep-ui">
    <div class="app-toggle-button" id="toggle-main">
        <i class="fa-solid fa-angle-up"></i>
    </div>
    <header class="app-header">
        <h1 class="app-title">Under The Witch's Room</h1>
        <div class="location-display">
            <span id="location-val">Loading...</span>
            <span id="date-val">--</span>
            <span id="time-val">--:--</span>
        </div>
    </header>

    <div class="app-content-wrapper" id="main-content-wrapper">
        <main class="app-content">
            <div id="panel-user" class="panel"></div>
            <div id="panel-kuro" class="panel"></div>
            <div id="panel-deborah" class="panel"></div>
        </main>
    </div>

    <nav class="app-navbar">
        <button class="nav-button" data-panel="panel-user">
            <i class="fa-solid fa-chess-pawn"></i>
            <span>玩具</span>
        </button>
        <button class="nav-button" data-panel="panel-kuro">
            <i class="fa-solid fa-crown"></i>
            <span>库洛</span>
        </button>
        <button class="nav-button" data-panel="panel-deborah">
            <i class="fa-solid fa-candy-cane"></i>
            <span>黛博拉</span>
        </button>
    </nav>
</div>

<script>
document.addEventListener('DOMContentLoaded', () => {
    const ui = document.querySelector('.witch-keep-ui');
    if (!ui) return;

    // --- Data Parsing ---
    function getNestedText(data, outer, inner) {
        const outerRegex = new RegExp(`\\[${outer}\\]([\\s\\S]*?)(?=\\[(?:魔女|玩具|全局)[^\\]]*\\]|$)`);
        const outerMatch = data.match(outerRegex);
        if (!outerMatch) return '';
        const innerRegex = new RegExp(`\\[${inner}\\]([\\s\\S]*?)(?=\\[|$)`);
        const innerMatch = outerMatch[1].match(innerRegex);
        return innerMatch ? innerMatch[1].trim() : '';
    }

    function getSectionText(data, sectionName) {
        const regex = new RegExp(`\\[${sectionName}\\]([\\s\\S]*?)(?=\\[(?:魔女|玩具|全局)[^\\]]*\\]|$)`, 'i');
        const match = data.match(regex);
        return match ? match[1].trim() : '';
    }

    function parseProperties(text) {
        if (!text) return {};
        return Object.fromEntries(text.split('|').map(part => {
            const [key, ...valueParts] = part.split(':');
            return [key.trim(), valueParts.join(':').trim()];
        }).filter(([key, value]) => key));
    }

    // --- UI Rendering ---
    const mainStatCard = (key, value) => `<div class="main-stat-card"><div class="stat-key">${key}</div><div class="stat-value">${value || '...'}</div></div>`;
    const subStatItem = (key, value) => `<div class="sub-stat-item"><div class="stat-key">${key}</div><div class="stat-value">${value || '...'}</div></div>`;
    const statItem = (key, value) => `<div class="stat-item"><span class="stat-key">${key}</span><span class="stat-value">${value || '...'}</span></div>`;
    const buildDetails = (title, content, contentClass = 'grid-layout') => `<details open><summary>${title}</summary><div class="details-content ${contentClass}">${content}</div></details>`;
    const buildThoughts = (text) => text ? `<div class="char-thoughts"><i class="fa-solid fa-comment-dots"></i><span>${text}</span></div>` : '';

    // --- Main Logic ---
    const rawDataContainer = document.querySelector('.raw-data-container');
    const rawData = rawDataContainer ? rawDataContainer.textContent : '';

    if (rawData) {
        // Global Info
        const globalInfo = parseProperties(getSectionText(rawData, '全局信息'));
        document.getElementById('location-val').textContent = globalInfo['地点'] || '...';
        document.getElementById('date-val').textContent = globalInfo['日期'] || '...';
        document.getElementById('time-val').textContent = globalInfo['时间'] || '...';

        // User Panel
        const userBase = parseProperties(getNestedText(rawData, '玩具状态', '基础'));
        const userSpirit = parseProperties(getNestedText(rawData, '玩具状态', '精神'));
        const userBody = parseProperties(getNestedText(rawData, '玩具状态', '肉体'));
        const userThoughts = getNestedText(rawData, '玩具状态', '思绪');

        document.getElementById('panel-user').innerHTML = `
            <div class="character-card">
                <div class="avatar-container"><div class="user_avatar"></div></div>
                <div class="char-info">
                    <div class="char-header">
                        <div class="char-name user">${userBase['名称']}</div>
                        <div class="char-title">${userBase['称号']} · ${userBase['阶级']}</div>
                    </div>
                </div>
            </div>
            <div class="details-section">
                ${buildDetails('精神',
                    statItem('意志', userSpirit['意志']) +
                    statItem('尊严', userSpirit['尊严']) +
                    statItem('屈服度', userSpirit['屈服度']) +
                    statItem('淫欲度', userSpirit['淫欲度']),
                    'grid-layout'
                )}
                ${buildDetails('肉体', `
                    <div class="section-layout">
                        ${mainStatCard('健康', userBody['健康'])}
                        ${mainStatCard('体力', userBody['体力'])}
                        <div class="sub-stats-grid full-width-grid">
                           ${subStatItem('阴茎状态', userBody['阴茎状态'])}
                           ${subStatItem('龟头敏感', userBody['龟头敏感'])}
                           ${subStatItem('乳头状态', userBody['乳头状态'])}
                           ${subStatItem('后庭状态', userBody['后庭状态'])}
                        </div>
                    </div>
                `, '')}
                ${buildThoughts(userThoughts)}
            </div>`;

        // Witches Panel Renderer
        const renderWitch = (witchId, witchName, witchCls) => {
            const base = parseProperties(getNestedText(rawData, witchId, '基础'));
            const emotion = parseProperties(getNestedText(rawData, witchId, '情绪'));
            const body = parseProperties(getNestedText(rawData, witchId, '身体'));
            const thoughts = getNestedText(rawData, witchId, '内心想法');

            document.getElementById(`panel-${witchCls}`).innerHTML = `
                <div class="character-card">
                    <div class="avatar-container"><div class="avatar avatar-${witchCls}"></div></div>
                    <div class="char-info">
                        <div class="char-header">
                            <div class="char-name ${witchCls}">${base['名称']}</div>
                            <div class="char-title">${base['称号']}</div>
                        </div>
                    </div>
                </div>
                <div class="details-section">
                    ${buildDetails('情绪', `
                        <div class="section-layout">
                            ${mainStatCard('心情', emotion['心情'])}
                             <div class="sub-stats-grid full-width-grid" style="grid-template-columns: 1fr;">
                                ${subStatItem('欲望', emotion['欲望'])}
                                ${subStatItem('对玩具的兴趣', emotion['对玩具的兴趣'])}
                            </div>
                        </div>
                    `, '')}
                    ${buildDetails('身体', `
                        <div class="sub-stats-grid" style="width: 100%;">
                            ${subStatItem('双乳状态', body['双乳状态'])}
                            ${subStatItem('小穴湿润', body['小穴湿润'])}
                            ${subStatItem('后庭状态', body['后庭状态'])}
                            ${subStatItem('玉足洁净', body['玉足洁净'])}
                        </div>
                    `, '')}
                    ${buildThoughts(thoughts)}
                </div>`;
        };
        renderWitch('魔女库洛', '库洛', 'kuro');
        renderWitch('魔女黛博拉', '黛博拉', 'deborah');
    }

    // --- Event Listeners ---
    const navButtons = ui.querySelectorAll('.nav-button');
    const panels = ui.querySelectorAll('.panel');
    navButtons.forEach(button => {
        button.addEventListener('click', () => {
            const panelId = button.dataset.panel;
            navButtons.forEach(btn => btn.classList.remove('active'));
            button.classList.add('active');
            panels.forEach(panel => {
                panel.classList.toggle('active', panel.id === panelId);
            });
        });
    });

    if (navButtons.length > 0) {
        navButtons[0].click();
    }

    const toggleButton = document.getElementById('toggle-main');
    toggleButton.addEventListener('click', () => document.body.classList.toggle('collapsed'));
});
</script>
</body>
</html>
